import { ark } from "@ark-ui/vue/factory";
import { Tabs as TabsPrimitive } from "@ark-ui/vue/tabs";
import {
  bottomNavigationItemRecipe,
  bottomNavigationRecipe,
} from "@pisagor/recipes/bottom-navigation";
import { defineComponent, h, type PropType } from "vue";

type ArkPart = Parameters<typeof h>[0];

// #region Types
export interface BottomNavigationItemProps {
  /**
   * Style recipe. Defaults to `bottomNavigationItemRecipe` from `@pisagor/recipes/bottom-navigation-item`.
   *
   * @defaultValue bottomNavigationItemRecipe
   */
  itemRecipe?: typeof bottomNavigationItemRecipe;
  class?: unknown;
}

export interface BottomNavigationRootProps {
  /**
   * Style recipe. Defaults to `bottomNavigationRecipe` from `@pisagor/recipes/bottom-navigation`.
   *
   * @defaultValue bottomNavigationRecipe
   */
  recipe?: typeof bottomNavigationRecipe;
  class?: unknown;
}
// #endregion

// #region Parts
export const BottomNavigationRoot = defineComponent({
  inheritAttrs: false,
  name: "BottomNavigationRoot",
  props: {
    class: { default: undefined, type: [String, Object, Array] as PropType<unknown> },
    recipe: {
      default: bottomNavigationRecipe,
      type: Function as PropType<typeof bottomNavigationRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.recipe();

      return h(
        TabsPrimitive.Root as ArkPart,
        {
          ...attrs,
          class: variantSlots.base({ class: props.class }),
        },
        slots,
      );
    };
  },
});

export const BottomNavigationList = defineComponent({
  inheritAttrs: false,
  name: "BottomNavigationList",
  props: {
    ariaLabel: { default: undefined, type: String },
    class: { default: undefined, type: [String, Object, Array] as PropType<unknown> },
    recipe: {
      default: bottomNavigationRecipe,
      type: Function as PropType<typeof bottomNavigationRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.recipe();

      return h(
        TabsPrimitive.List as ArkPart,
        {
          ...attrs,
          "aria-label": props.ariaLabel ?? (attrs["aria-label"] as string | undefined),
          class: variantSlots.list({ class: props.class }),
        },
        slots,
      );
    };
  },
});

export const BottomNavigationItem = defineComponent({
  inheritAttrs: false,
  name: "BottomNavigationItem",
  props: {
    class: { default: undefined, type: [String, Object, Array] as PropType<unknown> },
    itemRecipe: {
      default: bottomNavigationItemRecipe,
      type: Function as PropType<typeof bottomNavigationItemRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.itemRecipe();

      return h(
        TabsPrimitive.Trigger as ArkPart,
        {
          ...attrs,
          class: variantSlots.base({ class: props.class }),
        },
        slots,
      );
    };
  },
});

export const BottomNavigationItemIcon = defineComponent({
  inheritAttrs: false,
  name: "BottomNavigationItemIcon",
  props: {
    class: { default: undefined, type: [String, Object, Array] as PropType<unknown> },
    itemRecipe: {
      default: bottomNavigationItemRecipe,
      type: Function as PropType<typeof bottomNavigationItemRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.itemRecipe();

      return h(
        ark.span as ArkPart,
        {
          ...attrs,
          "aria-hidden": true,
          class: variantSlots.icon({ class: props.class }),
          "data-part": "item-icon",
          "data-scope": "bottom-navigation",
        },
        slots,
      );
    };
  },
});

export const BottomNavigationItemLabel = defineComponent({
  inheritAttrs: false,
  name: "BottomNavigationItemLabel",
  props: {
    class: { default: undefined, type: [String, Object, Array] as PropType<unknown> },
    itemRecipe: {
      default: bottomNavigationItemRecipe,
      type: Function as PropType<typeof bottomNavigationItemRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.itemRecipe();

      return h(
        ark.span as ArkPart,
        {
          ...attrs,
          class: variantSlots.label({ class: props.class }),
          "data-part": "item-label",
          "data-scope": "bottom-navigation",
        },
        slots,
      );
    };
  },
});
// #endregion

import {
  BottomNavigationItem,
  BottomNavigationItemIcon,
  BottomNavigationItemLabel,
  BottomNavigationList,
  BottomNavigationRoot,
} from "./bottom-navigation";

export const BottomNavigation = Object.assign(BottomNavigationRoot, {
  Item: BottomNavigationItem,
  ItemIcon: BottomNavigationItemIcon,
  ItemLabel: BottomNavigationItemLabel,
  List: BottomNavigationList,
});

import { ark } from "@ark-ui/vue/factory";
import { PhCaretRight, PhDotsThree } from "@phosphor-icons/vue";
import {
  type BreadcrumbItemRecipe,
  type BreadcrumbRecipe,
  breadcrumbItemRecipe,
  breadcrumbRecipe,
} from "@pisagor/recipes/breadcrumb";
import { defineComponent, h, type PropType, type VNodeChild } from "vue";
import { createContext } from "../../internal/utils/create-context";

// #region Types
export interface BreadcrumbPresetItem {
  href?: string;
  isCurrentPage?: boolean;
  label: VNodeChild;
}

export interface BreadcrumbRootProps {
  /**
   * Accessible label for the breadcrumb navigation landmark.
   *
   * @defaultValue "Breadcrumb"
   */
  ariaLabel?: string;
}

export interface BreadcrumbProps extends BreadcrumbRootProps {
  items?: BreadcrumbPresetItem[];
}

interface BreadcrumbContextValue {
  slots: BreadcrumbRecipe;
}

interface BreadcrumbItemContextValue {
  slots: BreadcrumbItemRecipe;
}

export interface BreadcrumbItemProps {
  /**
   * Style recipe. Defaults to `breadcrumbItemRecipe` from `@pisagor/recipes/breadcrumb-item`.
   *
   * @defaultValue breadcrumbItemRecipe
   */
  itemRecipe?: typeof breadcrumbItemRecipe;
  /**
   * Style recipe. Defaults to `breadcrumbRecipe` from `@pisagor/recipes/breadcrumb`.
   *
   * @defaultValue breadcrumbRecipe
   */
  recipe?: typeof breadcrumbRecipe;
  class?: unknown;
}
// #endregion

type ArkPart = Parameters<typeof h>[0];

// #region Context
const [provideBreadcrumbContext, useBreadcrumbContext] = createContext<BreadcrumbContextValue>({
  name: "Breadcrumb",
});

const [provideBreadcrumbItemContext, useBreadcrumbItemContext] =
  createContext<BreadcrumbItemContextValue>({
    name: "BreadcrumbItem",
  });
// #endregion

// #region Parts
export const BreadcrumbRoot = defineComponent({
  inheritAttrs: false,
  name: "BreadcrumbRoot",
  props: {
    ariaLabel: { default: "Breadcrumb", type: String },
    recipe: {
      default: breadcrumbRecipe,
      type: Function as PropType<typeof breadcrumbRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    const recipeSlots = props.recipe();

    provideBreadcrumbContext({ slots: recipeSlots });

    return () =>
      h(
        ark.nav as ArkPart,
        {
          ...attrs,
          "aria-label": props.ariaLabel,
          "data-part": "root",
          "data-scope": "breadcrumb",
        },
        slots,
      );
  },
});

export const BreadcrumbList = defineComponent({
  inheritAttrs: false,
  name: "BreadcrumbList",
  props: {
    class: { default: undefined, type: [String, Object, Array] as PropType<unknown> },
  },
  setup(props, { attrs, slots }) {
    const context = useBreadcrumbContext();

    return () =>
      h(
        ark.ol as ArkPart,
        {
          ...attrs,
          class: context?.slots.list({ class: props.class }),
          "data-part": "list",
          "data-scope": "breadcrumb",
          role: "list",
        },
        slots,
      );
  },
});

export const BreadcrumbItem = defineComponent({
  inheritAttrs: false,
  name: "BreadcrumbItem",
  props: {
    class: { default: undefined, type: [String, Object, Array] as PropType<unknown> },
    itemRecipe: {
      default: breadcrumbItemRecipe,
      type: Function as PropType<typeof breadcrumbItemRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    const recipeSlots = props.itemRecipe();

    provideBreadcrumbItemContext({ slots: recipeSlots });

    return () =>
      h(
        ark.li as ArkPart,
        {
          ...attrs,
          class: recipeSlots.base({ class: props.class }),
          "data-part": "item",
          "data-scope": "breadcrumb",
        },
        slots,
      );
  },
});

export const BreadcrumbLink = defineComponent({
  inheritAttrs: false,
  name: "BreadcrumbLink",
  props: {
    class: { default: undefined, type: [String, Object, Array] as PropType<unknown> },
  },
  setup(props, { attrs, slots }) {
    const context = useBreadcrumbItemContext();

    return () =>
      h(
        ark.a as ArkPart,
        {
          ...attrs,
          class: context?.slots.link({ class: props.class }),
          "data-part": "link",
          "data-scope": "breadcrumb",
        },
        slots,
      );
  },
});

export const BreadcrumbPage = defineComponent({
  inheritAttrs: false,
  name: "BreadcrumbPage",
  props: {
    class: { default: undefined, type: [String, Object, Array] as PropType<unknown> },
  },
  setup(props, { attrs, slots }) {
    const context = useBreadcrumbItemContext();

    return () =>
      h(
        ark.span as ArkPart,
        {
          ...attrs,
          "aria-current": "page",
          class: context?.slots.page({ class: props.class }),
          "data-part": "page",
          "data-scope": "breadcrumb",
        },
        slots,
      );
  },
});

export const BreadcrumbSeparator = defineComponent({
  inheritAttrs: false,
  name: "BreadcrumbSeparator",
  props: {
    class: { default: undefined, type: [String, Object, Array] as PropType<unknown> },
  },
  setup(props, { attrs, slots }) {
    const context = useBreadcrumbContext();

    return () =>
      h(
        ark.li as ArkPart,
        {
          ...attrs,
          "aria-hidden": "true",
          class: context?.slots.separator({ class: props.class }),
          "data-part": "separator",
          "data-scope": "breadcrumb",
          role: "presentation",
        },
        slots.default ?? (() => h(PhCaretRight)),
      );
  },
});

export const BreadcrumbEllipsis = defineComponent({
  inheritAttrs: false,
  name: "BreadcrumbEllipsis",
  setup(_, { attrs }) {
    const context = useBreadcrumbContext();

    return () =>
      h(
        ark.span as ArkPart,
        {
          ...attrs,
          "aria-hidden": "true",
          "data-part": "ellipsis",
          "data-scope": "breadcrumb",
          role: "presentation",
        },
        () => h(PhDotsThree, { class: context?.slots.ellipsis() }),
      );
  },
});

export const BreadcrumbShorthand = defineComponent({
  inheritAttrs: false,
  name: "BreadcrumbShorthand",
  props: {
    ariaLabel: { default: "Breadcrumb", type: String },
    items: { default: undefined, type: Array as PropType<BreadcrumbPresetItem[]> },
  },
  setup(props, { attrs }) {
    return () =>
      h(BreadcrumbRoot, { ...attrs, ariaLabel: props.ariaLabel }, () =>
        props.items
          ? h(BreadcrumbList, null, () =>
              props.items?.flatMap((item, index) => {
                const key = item.href ?? String(item.label);
                const nodes = [
                  h(BreadcrumbItem, { key }, () =>
                    item.isCurrentPage
                      ? h(BreadcrumbPage, null, () => item.label)
                      : item.href
                        ? h(BreadcrumbLink, { href: item.href }, () => item.label)
                        : item.label,
                  ),
                ];

                if (index > 0) {
                  nodes.unshift(h(BreadcrumbSeparator, { key: `separator-${key}` }));
                }

                return nodes;
              }),
            )
          : undefined,
      );
  },
});
// #endregion

import {
  BreadcrumbEllipsis,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbRoot,
  BreadcrumbSeparator,
  BreadcrumbShorthand,
} from "./breadcrumb";

export type { BreadcrumbPresetItem, BreadcrumbProps, BreadcrumbRootProps } from "./breadcrumb";

export const Breadcrumb = Object.assign(BreadcrumbShorthand, {
  Ellipsis: BreadcrumbEllipsis,
  Item: BreadcrumbItem,
  Link: BreadcrumbLink,
  List: BreadcrumbList,
  Page: BreadcrumbPage,
  Root: BreadcrumbRoot,
  Separator: BreadcrumbSeparator,
});

import { ark } from "@ark-ui/vue/factory";
import { type ButtonVariantProps, buttonRecipe } from "@pisagor/recipes/button";
import { defineComponent, h, type PropType } from "vue";
import { Spinner } from "../spinner";

// #region Types
export interface ButtonProps extends ButtonVariantProps {
  disabled?: boolean;
  type?: "button" | "reset" | "submit";
  /**
   * Style recipe. Defaults to `buttonRecipe` from `@pisagor/recipes/button`.
   *
   * @defaultValue buttonRecipe
   */
  recipe?: typeof buttonRecipe;
  class?: unknown;
}
// #endregion

type ArkPart = Parameters<typeof h>[0];

// #region Component
export const Button = defineComponent({
  inheritAttrs: false,
  name: "PisagorButton",
  props: {
    class: { default: undefined, type: [String, Object, Array] as PropType<unknown> },
    clickEffect: { default: true, type: Boolean },
    disabled: { default: undefined, type: Boolean },
    loading: { default: false, type: Boolean },
    pill: { default: false, type: Boolean },
    recipe: {
      default: buttonRecipe,
      type: Function as PropType<typeof buttonRecipe>,
    },
    size: {
      default: "md",
      type: String as PropType<NonNullable<ButtonVariantProps["size"]>>,
    },
    type: { default: "button", type: String as PropType<NonNullable<ButtonProps["type"]>> },
    variant: {
      default: "default",
      type: String as PropType<NonNullable<ButtonVariantProps["variant"]>>,
    },
  },
  setup(props, { attrs, slots: children }) {
    return () => {
      const slots = props.recipe({
        clickEffect: props.clickEffect,
        loading: props.loading,
        pill: props.pill,
        size: props.size,
        variant: props.variant,
      });

      return h(
        ark.button as ArkPart,
        {
          ...attrs,
          "aria-busy": props.loading || undefined,
          class: slots.base({ class: props.class }),
          "data-part": "root",
          "data-scope": "button",
          "data-size": props.size,
          "data-state": props.loading ? "loading" : "idle",
          "data-variant": props.variant,
          disabled: props.disabled || props.loading,
          type: props.type,
        },
        () =>
          props.loading
            ? [
                h("span", { "aria-hidden": true, class: slots.hidden() }, children.default?.()),
                h("span", { class: slots.srOnly() }, children.default?.()),
                h("span", { class: slots.spinner() }, () => h(Spinner, { "aria-hidden": true })),
              ]
            : children.default?.(),
      );
    };
  },
});
// #endregion

