          () => [
            h(InputGroup.Addon as ArkPart, null, () =>
              h(PhMagnifyingGlass, { "aria-hidden": true, class: variantSlots.inputIcon() }),
            ),
            h(ComboboxPrimitive.Input as ArkPart, { asChild: true }, () =>
              h(InputGroup.Input as ArkPart, {
