import { ark } from "@ark-ui/vue/factory";
import { Menu as MenuPrimitive } from "@ark-ui/vue/menu";
import { PhCaretRight, PhCheck } from "@phosphor-icons/vue";
import {
  type DropdownMenuItemVariantProps,
  dropdownMenuItemRecipe,
  dropdownMenuRecipe,
