import {
  Editable as EditablePrimitive,
  type EditableValueChangeDetails,
} from "@ark-ui/vue/editable";
import { buttonRecipe } from "@pisagor/recipes/button";
import { editableRecipe } from "@pisagor/recipes/editable";
