import { Field as FieldPrimitive } from "@ark-ui/vue/field";
import { Fieldset as FieldsetPrimitive } from "@ark-ui/vue/fieldset";
import { fieldRecipe } from "@pisagor/recipes/field";
import { formControlSeparatorRecipe } from "@pisagor/recipes/form-control";
import { cn } from "@pisagor/utils";
import { defineComponent, h, type PropType } from "vue";
import { Separator } from "../separator/separator";
import { useFormControlSurface } from "../surface/use-form-control-surface";

type FormControlVariant = "primary" | "secondary";

type ArkPart = Parameters<typeof h>[0];

// #region Types
export interface FieldProps {
  /**
   * Style recipe. Defaults to `fieldRecipe` from `@pisagor/recipes/field`.
   *
   * @defaultValue fieldRecipe
   */
  recipe?: typeof fieldRecipe;
  class?: unknown;
  orientation?: "horizontal" | "responsive" | "vertical";
  reverse?: boolean;
}

export interface FieldLabelProps {
  asChild?: boolean;
  class?: unknown;
}
// #endregion

// #region Parts
export const FieldRoot = defineComponent({
  inheritAttrs: false,
  name: "FieldRoot",
  props: {
    class: { default: undefined, type: [String, Object, Array] as PropType<unknown> },
    orientation: { default: "vertical", type: String as PropType<FieldProps["orientation"]> },
    recipe: {
      default: fieldRecipe,
      type: Function as PropType<typeof fieldRecipe>,
    },
    reverse: { default: false, type: Boolean },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.recipe({
        orientation: props.orientation,
        reverse: props.reverse,
      });

      return h(
        FieldPrimitive.Root as ArkPart,
        {
          ...attrs,
          class: cn(variantSlots.base(), props.class),
          "data-orientation": props.orientation,
        },
        slots,
      );
    };
  },
});

export const FieldSet = defineComponent({
  inheritAttrs: false,
  name: "FieldSet",
  props: {
    class: { default: undefined, type: [String, Object, Array] as PropType<unknown> },
    recipe: {
      default: fieldRecipe,
      type: Function as PropType<typeof fieldRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.recipe();

      return h(
        FieldsetPrimitive.Root as ArkPart,
        {
          ...attrs,
          class: cn(variantSlots.set(), props.class),
        },
        slots,
      );
    };
  },
});

export const FieldLegend = defineComponent({
  inheritAttrs: false,
  name: "FieldLegend",
  props: {
    class: { default: undefined, type: [String, Object, Array] as PropType<unknown> },
    recipe: {
      default: fieldRecipe,
      type: Function as PropType<typeof fieldRecipe>,
    },
    variant: { default: "legend", type: String as PropType<"label" | "legend"> },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.recipe();

      return h(
        FieldsetPrimitive.Legend as ArkPart,
        {
          ...attrs,
          class: cn(variantSlots.legend(), props.class),
          "data-variant": props.variant,
        },
        slots,
      );
    };
  },
});

export const FieldGroup = defineComponent({
  inheritAttrs: false,
  name: "FieldGroup",
  props: {
    class: { default: undefined, type: [String, Object, Array] as PropType<unknown> },
    recipe: {
      default: fieldRecipe,
      type: Function as PropType<typeof fieldRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.recipe();

      return h(
        "div",
        {
          ...attrs,
          class: cn(variantSlots.group(), props.class),
          "data-part": "group",
          "data-scope": "field",
        },
        slots.default?.(),
      );
    };
  },
});

export const FieldContent = defineComponent({
  inheritAttrs: false,
  name: "FieldContent",
  props: {
    class: { default: undefined, type: [String, Object, Array] as PropType<unknown> },
    recipe: {
      default: fieldRecipe,
      type: Function as PropType<typeof fieldRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.recipe();

      return h(
        "div",
        {
          ...attrs,
          class: cn(variantSlots.content(), props.class),
          "data-part": "content",
          "data-scope": "field",
        },
        slots.default?.(),
      );
    };
  },
});

export const FieldLabel = defineComponent({
  inheritAttrs: false,
  name: "FieldLabel",
  props: {
    asChild: Boolean,
    class: { default: undefined, type: [String, Object, Array] as PropType<unknown> },
    recipe: {
      default: fieldRecipe,
      type: Function as PropType<typeof fieldRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.recipe();

      return h(
        FieldPrimitive.Label as ArkPart,
        {
          ...attrs,
          asChild: props.asChild,
          class: cn(variantSlots.label(), props.class),
        },
        slots,
      );
    };
  },
});

export const FieldRequiredIndicator = defineComponent({
  inheritAttrs: false,
  name: "FieldRequiredIndicator",
  props: {
    class: { default: undefined, type: [String, Object, Array] as PropType<unknown> },
    recipe: {
      default: fieldRecipe,
      type: Function as PropType<typeof fieldRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.recipe();

      return h(
        FieldPrimitive.RequiredIndicator as ArkPart,
        {
          ...attrs,
          "aria-hidden": true,
          class: cn(variantSlots.requiredIndicator(), props.class),
        },
        () => slots.default?.() ?? "*",
      );
    };
  },
});

export const FieldTitle = defineComponent({
  inheritAttrs: false,
  name: "FieldTitle",
  props: {
    class: { default: undefined, type: [String, Object, Array] as PropType<unknown> },
    recipe: {
      default: fieldRecipe,
      type: Function as PropType<typeof fieldRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.recipe();

      return h(
        "div",
        {
          ...attrs,
          class: cn(variantSlots.title(), props.class),
          "data-part": "title",
          "data-scope": "field",
        },
        slots.default?.(),
      );
    };
  },
});

export const FieldDescription = defineComponent({
  inheritAttrs: false,
  name: "FieldDescription",
  props: {
    class: { default: undefined, type: [String, Object, Array] as PropType<unknown> },
    recipe: {
      default: fieldRecipe,
      type: Function as PropType<typeof fieldRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.recipe();

      return h(
        "p",
        {
          ...attrs,
          class: cn(variantSlots.description(), props.class),
          "data-part": "description",
          "data-scope": "field",
        },
        slots.default?.(),
      );
    };
  },
});

export const FieldSeparator = defineComponent({
  inheritAttrs: false,
  name: "FieldSeparator",
  props: {
    class: { default: undefined, type: [String, Object, Array] as PropType<unknown> },
    recipe: {
      default: fieldRecipe,
      type: Function as PropType<typeof fieldRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    const surfaceVariant = useFormControlSurface();

    return () => {
      const resolved = { surfaceVariant, variant: "primary" as FormControlVariant };
      const shellArgs = {
        surfaceVariant: resolved.surfaceVariant,
        variant: resolved.variant,
      };
      const children = slots.default?.();
      const variantSlots = props.recipe();

      return h(
        "div",
        {
          ...attrs,
          class: cn(variantSlots.separator(), props.class),
          "data-content": !!children,
          "data-part": "separator",
          "data-scope": "field",
        },
        [
          h(Separator as ArkPart, { class: variantSlots.inline() }),
          children
            ? h("span", { class: cn(formControlSeparatorRecipe({ ...shellArgs })) }, children)
            : null,
        ],
      );
    };
  },
});

export const FieldHelper = defineComponent({
  inheritAttrs: false,
  name: "FieldHelper",
  props: {
    class: { default: undefined, type: [String, Object, Array] as PropType<unknown> },
    recipe: {
      default: fieldRecipe,
      type: Function as PropType<typeof fieldRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.recipe();

      return h(
        FieldPrimitive.HelperText as ArkPart,
        {
          ...attrs,
          class: cn(variantSlots.helper(), props.class),
        },
        slots,
      );
    };
  },
});

export const FieldError = defineComponent({
  inheritAttrs: false,
  name: "FieldError",
  props: {
    class: { default: undefined, type: [String, Object, Array] as PropType<unknown> },
    recipe: {
      default: fieldRecipe,
      type: Function as PropType<typeof fieldRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.recipe();

      return h(
        FieldPrimitive.ErrorText as ArkPart,
        {
          ...attrs,
          class: cn(variantSlots.error(), props.class),
        },
        slots,
      );
    };
  },
});
// #endregion

