import {
  type FileUploadFileChangeDetails,
  FileUpload as FileUploadPrimitive,
  useFileUploadContext,
} from "@ark-ui/vue/file-upload";
import { PhUpload, PhX } from "@phosphor-icons/vue";
import { fileUploadItemRecipe, fileUploadRecipe } from "@pisagor/recipes/file-upload";
import { formControlZoneRecipe } from "@pisagor/recipes/form-control";
import { cn } from "@pisagor/utils";
import { defineComponent, h, type PropType } from "vue";
import { Button } from "../button";
import { useFormControlSurface } from "../surface/use-form-control-surface";

type FormControlVariant = "primary" | "secondary";

type ArkPart = Parameters<typeof h>[0];

// #region Types
export interface FileUploadRootProps {
  onValueChange?: (value: File[]) => void;
  /**
   * Style recipe. Defaults to `fileUploadRecipe` from `@pisagor/recipes/file-upload`.
   *
   * @defaultValue fileUploadRecipe
   */
  recipe?: typeof fileUploadRecipe;
  class?: unknown;
}

interface FileUploadDropzoneProps {
  class?: unknown;
  /** Visual shell variant. Defaults to `primary`. */
  variant?: FormControlVariant;
}

export interface FileUploadItemProps {
  /**
   * Style recipe. Defaults to `fileUploadItemRecipe` from `@pisagor/recipes/file-upload`.
   *
   * @defaultValue fileUploadItemRecipe
   */
  itemRecipe?: typeof fileUploadItemRecipe;
  class?: unknown;
}
// #endregion

// #region Parts
export const FileUploadRoot = defineComponent({
  inheritAttrs: false,
  name: "FileUpload",
  props: {
    class: { default: undefined, type: [String, Object, Array] as PropType<unknown> },
    onValueChange: {
      default: undefined,
      type: Function as PropType<FileUploadRootProps["onValueChange"]>,
    },
    recipe: {
      default: fileUploadRecipe,
      type: Function as PropType<typeof fileUploadRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const onFileChange = attrs.onFileChange as
        | ((details: FileUploadFileChangeDetails) => void)
        | undefined;
      const variantSlots = props.recipe();

      return h(
        FileUploadPrimitive.Root as ArkPart,
        {
          ...attrs,
          class: variantSlots.base({ class: props.class }),
          onFileChange: (details: FileUploadFileChangeDetails) => {
            onFileChange?.(details);
            props.onValueChange?.(details.acceptedFiles);
          },
        },
        () => [slots.default?.(), h(FileUploadPrimitive.HiddenInput as ArkPart)],
      );
    };
  },
});

export const FileUploadTrigger = defineComponent({
  inheritAttrs: false,
  name: "FileUpload.Trigger",
  setup(_, { attrs, slots }) {
    return () => h(FileUploadPrimitive.Trigger as ArkPart, { ...attrs }, slots);
  },
});

export const FileUploadDropzone = defineComponent({
  inheritAttrs: false,
  name: "FileUpload.Dropzone",
  props: {
    class: { default: undefined, type: [String, Object, Array] as PropType<unknown> },
    recipe: {
      default: fileUploadRecipe,
      type: Function as PropType<typeof fileUploadRecipe>,
    },
    variant: { default: undefined, type: String as PropType<FileUploadDropzoneProps["variant"]> },
  },
  setup(props, { attrs, slots }) {
    const surfaceVariant = useFormControlSurface();

    return () => {
      const resolved = {
        surfaceVariant,
        variant: props.variant ?? ("primary" as FormControlVariant),
      };
      const shellArgs = {
        surfaceVariant: resolved.surfaceVariant,
        variant: resolved.variant,
      };
      const controlProps = { "data-variant": resolved.variant };
      const variantSlots = props.recipe();

      return h(
        FileUploadPrimitive.Dropzone as ArkPart,
        {
          ...attrs,
          ...controlProps,
          class: cn(formControlZoneRecipe({ ...shellArgs }), variantSlots.dropzone(), props.class),
        },
        slots,
      );
    };
  },
});

