export const Controlled = meta.story({
  render: () => ({
    components: { Input },
    setup() {
      const value = ref("");
      const onValueChange = (next: string) => {
        value.value = next;
      };
      return { onValueChange, value };
    },
    template:
      '<Input :onValueChange="onValueChange" :value="value" placeholder="Enter your message" />',
  }),
});

