});

export const Handle = meta.story({
  render: () => ({
    components: { Resizable },
    template: `
      <div class="${frameClass()}">
        <Resizable class="size-full rounded-md border" :defaultSize="[50, 50]" :panels="[{ id: '1' }, { id: '2' }]">
          <Resizable.Panel class="${panelClassName()}" id="1">
