          </aside>
          <div class="flex min-w-0 flex-1 items-center justify-center bg-muted/30 text-sm">
            Main
          </div>
        </div>
      </div>
    `,
  }),
});

export const MultiplePanels = meta.story({
  render: () => ({
    components: { Resizable },
