export const Invalid = meta.story({
  render: () => ({
    components: { Select },
    setup() {
      return {
        items: [
          { label: "Next.js", value: "next" },
          { label: "Vite", value: "vite" },
          { label: "Astro", value: "astro" },
        ],
      };
    },
    template: `
      <Select invalid :items="items" placeholder="Select framework" />
