import { ark } from "@ark-ui/vue/factory";
import { skipNavRecipe } from "@pisagor/recipes/skip-nav";
import { cn } from "@pisagor/utils";
import { defineComponent, h, type PropType } from "vue";

// #region Types
export interface SkipNavLinkProps {
  /**
   * The id of the element to skip to.
   *
   * @defaultValue "skip-nav-content"
   *
   * @remarks
   * Must match the `id` on the paired `SkipNavContent`.
   */
  id?: string;
  /**
   * Style recipe. Defaults to `skipNavRecipe` from `@pisagor/recipes/skip-nav`.
   *
   * @defaultValue skipNavRecipe
   */
  recipe?: typeof skipNavRecipe;
  class?: unknown;
}

export interface SkipNavContentProps {
  /**
   * The id that SkipNavLink links to.
   *
   * @defaultValue "skip-nav-content"
   *
   * @remarks
   * Must match the `id` passed to the paired `SkipNavLink`.
   */
  id?: string;
  class?: unknown;
}
// #endregion

type ArkPart = Parameters<typeof h>[0];

const SKIP_NAV_ID = "skip-nav-content";

// #region Parts
export const SkipNavLink = defineComponent({
  inheritAttrs: false,
  name: "SkipNavLink",
  props: {
    class: { default: undefined, type: [String, Object, Array] as PropType<unknown> },
    id: { default: SKIP_NAV_ID, type: String },
    recipe: {
      default: skipNavRecipe,
      type: Function as PropType<typeof skipNavRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    const variantSlots = props.recipe();

    return () =>
      h(
        ark.a as ArkPart,
        {
          ...attrs,
          class: cn(variantSlots.link(), props.class, attrs.class),
          "data-part": "link",
          "data-scope": "skip-nav",
          href: `#${props.id}`,
        },
        slots.default ?? (() => "Skip to content"),
      );
  },
});

export const SkipNavContent = defineComponent({
  inheritAttrs: false,
  name: "SkipNavContent",
  props: {
    class: { default: undefined, type: [String, Object, Array] as PropType<unknown> },
    id: { default: SKIP_NAV_ID, type: String },
    recipe: {
      default: skipNavRecipe,
      type: Function as PropType<typeof skipNavRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    const variantSlots = props.recipe();

    return () =>
      h(
        ark.div as ArkPart,
        {
          ...attrs,
          class: cn(variantSlots.content(), props.class, attrs.class),
          "data-part": "content",
          "data-scope": "skip-nav",
          id: props.id,
          tabIndex: -1,
        },
        slots,
      );
  },
});
// #endregion

import { SkipNavContent, SkipNavLink } from "./skip-nav";

export type { SkipNavContentProps, SkipNavLinkProps } from "./skip-nav";

export const SkipNav = {
  Content: SkipNavContent,
  Link: SkipNavLink,
};

