import { type SurfaceVariantProps, surfaceRecipe } from "@pisagor/recipes/surface";
import { cn } from "@pisagor/utils";
import { computed, defineComponent, h, type PropType } from "vue";
import { createContext } from "../../internal/utils/create-context";

export type SurfaceVariant = NonNullable<SurfaceVariantProps["variant"]>;

export interface SurfaceContextValue {
  depth: number;
  variant: SurfaceVariant;
}

const AUTO_VARIANTS = [
  "default",
  "secondary",
  "tertiary",
  "tertiary",
] as const satisfies readonly SurfaceVariant[];

export const [provideSurfaceContext, useSurfaceContext] = createContext<SurfaceContextValue>({
  name: "PisagorSurface",
  strict: false,
});

export function useSurface() {
  return useSurfaceContext();
}

export interface SurfaceProps extends SurfaceVariantProps {
  /**
   * Style recipe. Defaults to `surfaceRecipe` from `@pisagor/recipes/surface`.
   *
   * @defaultValue surfaceRecipe
   */
  recipe?: typeof surfaceRecipe;
  class?: unknown;
}

type ArkPart = Parameters<typeof h>[0];

export const Surface = defineComponent({
  inheritAttrs: false,
  name: "PisagorSurface",
  props: {
    bordered: { default: false, type: Boolean },
    class: { default: undefined, type: [String, Object, Array] as PropType<unknown> },
    padding: { default: undefined, type: String as PropType<SurfaceVariantProps["padding"]> },
    recipe: {
      default: surfaceRecipe,
      type: Function as PropType<typeof surfaceRecipe>,
    },
    rounded: { default: true, type: Boolean },
    variant: { default: undefined, type: String as PropType<SurfaceVariant> },
  },
  setup(props, { attrs, slots }) {
    const parent = useSurface();

    const surface = computed(() => {
      const depth = parent ? parent.depth + 1 : 0;
      const variant =
        props.variant ?? AUTO_VARIANTS[Math.min(depth, AUTO_VARIANTS.length - 1)] ?? "default";

      return { depth, variant };
    });

    provideSurfaceContext(surface);

    return () =>
      h(
        "div" as ArkPart,
        {
          ...attrs,
          class: cn(
            props.recipe({
              bordered: props.bordered,
              padding: props.padding,
              rounded: props.rounded,
              variant: surface.value.variant,
            }),
            props.class,
          ),
          "data-depth": surface.value.depth,
          "data-part": "root",
          "data-scope": "surface",
          "data-variant": surface.value.variant,
        },
        slots.default?.(),
      );
  },
});

export type { SurfaceContextValue, SurfaceProps, SurfaceVariant } from "./surface";
export { provideSurfaceContext, Surface, useSurface } from "./surface";

export type { FormControlSurfaceVariant } from "./use-form-control-surface";
export { useFormControlSurface } from "./use-form-control-surface";

import { Swap as SwapPrimitive } from "@ark-ui/vue/swap";
import { type SwapVariantProps, swapRecipe } from "@pisagor/recipes/swap";
import { cn } from "@pisagor/utils";
import { defineComponent, h, type PropType, type VNodeChild } from "vue";

// #region Types
export type SwapVariant = NonNullable<SwapVariantProps["variant"]>;

export interface SwapProps extends SwapVariantProps {
  /**
   * Style recipe. Defaults to `swapRecipe` from `@pisagor/recipes/swap`.
   *
   * @defaultValue swapRecipe
   */
  recipe?: typeof swapRecipe;
  class?: unknown;
  lazyMount?: boolean;
  /**
   * Whether the swap shows the `on` or `off` indicator.
   *
   * @remarks
   * Mirrored from Ark UI’s `swap` prop.
   */
  swap?: boolean;
  unmountOnExit?: boolean;
  /** Content shown when swapped on. */
  on?: VNodeChild;
  /** Content shown when swapped off. */
  off?: VNodeChild;
  /** Extra props forwarded to the `on` indicator element. */
  onIndicatorProps?: Record<string, unknown>;
  /** Extra props forwarded to the `off` indicator element. */
  offIndicatorProps?: Record<string, unknown>;
}

type ArkPart = Parameters<typeof h>[0];

// #region Parts
export const Swap = defineComponent({
  inheritAttrs: false,
  name: "PisagorSwap",
  props: {
    class: { default: undefined, type: [String, Object, Array] as PropType<unknown> },
    lazyMount: { default: true, type: Boolean },
    off: { default: undefined, type: [String, Object, Array, Function] as PropType<VNodeChild> },
    offIndicatorProps: { default: undefined, type: Object as PropType<Record<string, unknown>> },
    on: { default: undefined, type: [String, Object, Array, Function] as PropType<VNodeChild> },
    onIndicatorProps: { default: undefined, type: Object as PropType<Record<string, unknown>> },
    recipe: {
      default: swapRecipe,
      type: Function as PropType<typeof swapRecipe>,
    },
    swap: { default: false, type: Boolean },
    unmountOnExit: { default: true, type: Boolean },
    variant: { default: "fade", type: String as PropType<SwapVariant> },
  },
  setup(props, { attrs, slots }) {
    return () =>
      h(
        SwapPrimitive.Root as ArkPart,
        {
          ...attrs,
          class: cn(props.recipe({ variant: props.variant }), props.class),
          lazyMount: props.lazyMount,
          swap: props.swap,
          unmountOnExit: props.unmountOnExit,
        },
        () => [
          props.on !== undefined
            ? h(
                SwapPrimitive.Indicator as ArkPart,
                {
                  ...(props.onIndicatorProps ?? {}),
                  type: "on",
                },
                () => props.on,
              )
            : null,
          props.off !== undefined
            ? h(
                SwapPrimitive.Indicator as ArkPart,
                {
                  ...(props.offIndicatorProps ?? {}),
                  type: "off",
                },
                () => props.off,
              )
            : null,
          slots.default?.(),
        ],
      );
  },
});
// #endregion

