import { ark } from "@ark-ui/vue/factory";
import { tableRecipe } from "@pisagor/recipes/table";
import { defineComponent, h, type PropType } from "vue";

// #region Types
export interface TableProps {
  /**
   * Whether the table rows are hoverable.
   *
   * @defaultValue true
   */
  isHoverable?: boolean;
  /**
   * The variant of the table.
   *
   * @defaultValue "plain"
   */
  variant?: "plain" | "striped";
  /**
   * Style recipe. Defaults to `tableRecipe` from `@pisagor/recipes/table`.
   *
   * @defaultValue tableRecipe
   */
  recipe?: typeof tableRecipe;
  class?: unknown;
}

type ArkPart = Parameters<typeof h>[0];
// #endregion

// #region Parts
export const TableRoot = defineComponent({
  inheritAttrs: false,
  name: "TableRoot",
  props: {
    class: { default: undefined, type: [String, Object, Array] as PropType<unknown> },
    isHoverable: { default: true, type: Boolean },
    recipe: {
      default: tableRecipe,
      type: Function as PropType<typeof tableRecipe>,
    },
    variant: { default: "plain", type: String as PropType<TableProps["variant"]> },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.recipe();

      return h(
        "div" as ArkPart,
        {
          class: variantSlots.wrapper(),
          "data-part": "wrapper",
          "data-scope": "table",
        },
        () =>
          h(
            ark.table as ArkPart,
            {
              ...attrs,
              class: variantSlots.base({ class: props.class }),
              "data-hoverable": props.isHoverable ? "true" : undefined,
              "data-part": "root",
              "data-scope": "table",
              "data-variant": props.variant,
            },
            slots.default?.(),
