    },
    template: '<Button @click="handleClick" variant="outline">Run Promise</Button>',
  }),
});

export const Placements = meta.story({
  render: () => ({
    components: { Button, Toaster },
    setup() {
      const topStartToaster = createToaster({
        overlap: true,
