import { waitForElement, waitForEvent } from "@ark-ui/vue/tour";
import { PhKeyboard, PhPlus } from "@phosphor-icons/vue";
import type { TourStepType } from "@pisagor/vue";
import { Button, Checkbox, Field, Input, Tour, useTourContext } from "@pisagor/vue";
import { defineComponent, h, ref, toValue } from "vue";
import preview from "#/storybook/preview";

const meta = preview.meta({
  component: Tour,
  parameters: {
    docs: {
      description: {
        component:
          "Walks new users through key parts of the interface step by step with guided highlights.",
      },
    },
    metadata: {
      api: "compound",
      taxonomy: "pattern",
    },
  },
  subcomponents: {
    Actions: Tour.Actions,
    ActionTrigger: Tour.ActionTrigger,
    Backdrop: Tour.Backdrop,
    Body: Tour.Body,
